import json
import logging
import uuid
import datetime
from typing import Callable, Dict, List, Any

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("AEGIS_EVENT_BUS")

class EventBus:
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super(EventBus, cls).__new__(cls)
            cls._instance.subscribers: Dict[str, List[Callable]] = {}
            cls._instance.event_log: List[Dict[str, Any]] = []
        return cls._instance

    def subscribe(self, event_type: str, handler: Callable):
        if event_type not in self.subscribers:
            self.subscribers[event_type] = []
        self.subscribers[event_type].append(handler)
        logger.info(f"Subscribed {handler.__name__} to event: {event_type}")

    def publish(self, event_type: str, payload: Dict[str, Any], correlation_id: str = None, saga_id: str = None) -> Dict[str, Any]:
        event_id = payload.get("event_id") or str(uuid.uuid4())
        correlation_id = correlation_id or payload.get("correlation_id") or str(uuid.uuid4())
        saga_id = saga_id or payload.get("saga_id") or payload.get("project_id") or str(uuid.uuid4())

        event = {
            "event_id": event_id,
            "event_type": event_type,
            "correlation_id": correlation_id,
            "saga_id": saga_id,
            "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            "payload": payload
        }

        self.event_log.append(event)
        logger.info(f"⚡ [EVENT PUBLISHED] [{event_type}] | SagaID: {saga_id[:8]}... | EventID: {event_id[:8]}...")

        # Dispatch to subscribers
        if event_type in self.subscribers:
            for handler in self.subscribers[event_type]:
                try:
                    handler(event)
                except Exception as e:
                    logger.error(f"Error executing handler {handler.__name__} for {event_type}: {e}")

        return event

bus = EventBus()

