from typing import Optional

logger = logging.getLogger("AEGIS_IDEMPOTENCY")

class IdempotencyHandler:
    def __init__(self, db_conn=None):
        self.db_conn = db_conn
        self.local_processed = set() # In-memory fallback tracking

    def is_processed(self, event_id: str, service_name: str = "default") -> bool:
        if not event_id:
            return False

        if self.db_conn:
            try:
                cursor = self.db_conn.cursor()
                cursor.execute("SELECT 1 FROM processed_events WHERE event_id = %s;", (event_id,))
                row = cursor.fetchone()
                return row is not None
            except Exception as e:
                logger.warning(f"DB error checking idempotency in {service_name}: {e}")

        return event_id in self.local_processed

    def mark_processed(self, event_id: str, event_type: str, service_name: str = "default") -> bool:
        if not event_id:
            return False

        self.local_processed.add(event_id)

        if self.db_conn:
            try:
                cursor = self.db_conn.cursor()
                cursor.execute(
                    "INSERT INTO processed_events (event_id, event_type) VALUES (%s, %s) ON CONFLICT (event_id) DO NOTHING;",
                    (event_id, event_type)
                )
                self.db_conn.commit()
                return True
            except Exception as e:
                logger.error(f"Failed to record idempotency row in {service_name}: {e}")
                return False
        return True

import logging
import uuid
import datetime
from shared.event_bus import bus
from shared.idempotency import IdempotencyHandler
from shared.config import TOPICS

logger = logging.getLogger("FUNDING_SERVICE")

class FundingService:
    def __init__(self):
        self.idempotency = IdempotencyHandler()
        self.grants = {
            "GRANT-WESTERN-GHATS-2026": {
                "title": "Western Ghats Biodiversity & Conservation Fund",
                "total_budget": 5000000.00,
                "reserved_budget": 0.00,
                "spent_budget": 0.00
            },
            "GRANT-HERITAGE-ASI-2026": {
                "title": "Archaeological Survey Heritage Protection Fund",
                "total_budget": 3500000.00,
                "reserved_budget": 0.00,
                "spent_budget": 0.00
            }
        }
        self.allocations = {}
        self.ledger = []
        self._register_subscribers()

    def _register_subscribers(self):
        bus.subscribe(TOPICS["COMMAND_RESERVE_FUNDS"], self.handle_reserve_funds)
        bus.subscribe(TOPICS["COMMAND_RELEASE_FUNDS"], self.handle_release_funds)

    def handle_reserve_funds(self, event: dict):
        payload = event["payload"]
        event_id = event["event_id"]
        project_id = payload["project_id"]

        if self.idempotency.is_processed(event_id, "funding_service"):
            return
        self.idempotency.mark_processed(event_id, event["event_type"], "funding_service")

        grant_code = payload.get("grant_code", "GRANT-WESTERN-GHATS-2026")
        amount = payload.get("amount", 250000.00)
        grant = self.grants.get(grant_code)

        if not grant or (grant["total_budget"] - grant["reserved_budget"]) < amount:
            logger.warning(f"❌ [FUNDING SERVICE] Insufficient funds in grant {grant_code} for Project {project_id[:8]}")
            bus.publish(TOPICS["FUNDS_INSUFFICIENT"], {
                "event_id": str(uuid.uuid4()),
                "project_id": project_id,
                "saga_id": payload["saga_id"],
                "reason": "Grant budget limit exceeded"
            })
            return

        grant["reserved_budget"] += amount
        self.allocations[project_id] = {"grant_code": grant_code, "amount": amount}
        self.ledger.append({
            "ledger_id": str(uuid.uuid4()),
            "project_id": project_id,
            "type": "RESERVE",
            "amount": amount,
            "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat()
        })

        logger.info(f"💰 [FUNDING SERVICE] Reserved ${amount:,.2f} from {grant_code} for Project {project_id[:8]}")

        bus.publish(TOPICS["FUNDS_RESERVED"], {
            "event_id": str(uuid.uuid4()),
            "project_id": project_id,
            "saga_id": payload["saga_id"],
            "grant_code": grant_code,
            "reserved_amount": amount
        })

    def handle_release_funds(self, event: dict):
        payload = event["payload"]
        event_id = event["event_id"]
        project_id = payload["project_id"]

        if self.idempotency.is_processed(event_id, "funding_service"):
            return
        self.idempotency.mark_processed(event_id, event["event_type"], "funding_service")

        alloc = self.allocations.pop(project_id, None)
        if alloc:
            grant = self.grants.get(alloc["grant_code"])
            if grant:
                grant["reserved_budget"] = max(0.0, grant["reserved_budget"] - alloc["amount"])
            self.ledger.append({
                "ledger_id": str(uuid.uuid4()),
                "project_id": project_id,
                "type": "RELEASE_COMPENSATION",
                "amount": alloc["amount"],
                "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat()
            })
            logger.info(f"💵 [FUNDING SERVICE COMPENSATION] Released ${alloc['amount']:,.2f} back to Grant for Project {project_id[:8]}")

        bus.publish(TOPICS["FUNDS_RELEASED"], {
            "event_id": str(uuid.uuid4()),
            "project_id": project_id,
            "saga_id": payload["saga_id"],
            "status": "RELEASED"
        })

funding_service = FundingService()

import logging
