from shared.config import TOPICS

logger = logging.getLogger("REGULATORY_SERVICE")

class RegulatoryGateway:
    def __init__(self):
        self.idempotency = IdempotencyHandler()
        self.permits = {}
        # Mode can be 'HAPPY_PATH' or 'FORCE_REJECT' for interactive Saga demonstration
        self.mode = "HAPPY_PATH"
        self._register_subscribers()

    def set_simulation_mode(self, mode: str):
        self.mode = mode
        logger.info(f"🏛️ [REGULATORY GATEWAY] Simulation mode updated to: {self.mode}")

    def _register_subscribers(self):
        bus.subscribe(TOPICS["COMMAND_REQUEST_PERMIT"], self.handle_request_permit)

    def handle_request_permit(self, event: dict):
        payload = event["payload"]
        event_id = event["event_id"]
        project_id = payload["project_id"]

        if self.idempotency.is_processed(event_id, "regulatory_service"):
            return
        self.idempotency.mark_processed(event_id, event["event_type"], "regulatory_service")

        location_name = payload.get("location_name", "Western Ghats Region")

        if self.mode == "FORCE_REJECT":
            logger.warning(f"🏛️ [REGULATORY GATEWAY] Permit Request REJECTED for Project {project_id[:8]} (Mode: FORCE_REJECT)")
            self.permits[project_id] = {
                "status": "REJECTED",
                "issuing_agency": "Karnataka Forest Department & Wildlife Board",
                "rejection_reason": "Project site intersects protected tiger corridor; drone flight permit denied."
            }
            bus.publish(TOPICS["PERMIT_REJECTED"], {
                "event_id": str(uuid.uuid4()),
                "project_id": project_id,
                "saga_id": payload["saga_id"],
                "issuing_agency": "Karnataka Forest Department",
                "rejection_reason": "Site intersects protected tiger corridor; drone flight permit denied."
            })
        else:
            logger.info(f"🏛️ [REGULATORY GATEWAY] Permit Request APPROVED for Project {project_id[:8]}")
            self.permits[project_id] = {
                "status": "APPROVED",
                "issuing_agency": "Ministry of Environment, Forest & Climate Change",
                "approval_date": datetime.datetime.now(datetime.timezone.utc).isoformat()
            }
            bus.publish(TOPICS["PERMIT_APPROVED"], {
                "event_id": str(uuid.uuid4()),
                "project_id": project_id,
                "saga_id": payload["saga_id"],
                "issuing_agency": "Ministry of Environment, Forest & Climate Change"
            })

regulatory_gateway = RegulatoryGateway()

:root {
    --bg-dark: #0B0F19;
    --card-bg: rgba(17, 24, 39, 0.85);
    --card-border: rgba(255, 255, 255, 0.08);
    --accent-blue: #00F2FE;
    --accent-indigo: #4FACFE;
    --accent-green: #00E676;
    --accent-red: #FF5252;
    --accent-orange: #FF9100;
    --text-main: #F3F4F6;
    --text-muted: #9CA3AF;
    --font-heading: 'Outfit', sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    background-color: var(--bg-dark);
    background-image: 
        radial-gradient(circle at 15% 15%, rgba(0, 242, 254, 0.05) 0%, transparent 40%),
        radial-gradient(circle at 85% 85%, rgba(79, 172, 254, 0.05) 0%, transparent 40%);
    color: var(--text-main);
    font-family: var(--font-heading);
    min-height: 100vh;
    overflow-x: hidden;
}

.app-container {
    display: flex;
    flex-direction: column;
    height: 100vh;
    padding: 1rem;
    gap: 1rem;
}

/* Header Navbar */
.top-nav {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: var(--card-bg);
    border: 1px solid var(--card-border);
    backdrop-filter: blur(16px);
    border-radius: 14px;
    padding: 0.85rem 1.5rem;
}

.brand {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.logo-badge {
    background: linear-gradient(135deg, var(--accent-blue), var(--accent-indigo));
    width: 44px;
    height: 44px;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 4px 20px rgba(0, 242, 254, 0.3);
}

.logo-icon {
    font-size: 1.4rem;
}

.brand-text h1 {
    font-size: 1.35rem;
    font-weight: 700;
    letter-spacing: 0.5px;
    background: linear-gradient(90deg, #FFFFFF, var(--accent-blue));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.brand-text p {
    font-size: 0.78rem;
    color: var(--text-muted);
}

.header-badges {
    display: flex;
    gap: 0.75rem;
}

.status-chip {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid var(--card-border);
    padding: 0.4rem 0.85rem;
    border-radius: 20px;
    font-size: 0.8rem;
}

.status-chip.active {
    border-color: rgba(0, 230, 118, 0.3);
    background: rgba(0, 230, 118, 0.08);
}

.pulse-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;

}

.pulse-dot.green {
    background: var(--accent-green);
    box-shadow: 0 0 8px var(--accent-green);
}

.chip-label {
    color: var(--text-muted);
}

.chip-val {
    font-weight: 600;
    color: var(--accent-blue);
}

/* Dashboard Grid Layout */
.dashboard-grid {
    display: grid;
    grid-template-columns: 340px 1fr 320px;
    gap: 1rem;
    flex: 1;
    min-height: 0;
}

.sidebar-panel, .center-panel {
    display: flex;
    flex-direction: column;
    gap: 1rem;
    overflow-y: auto;
}

/* Card Styling */
.card {
    background: var(--card-bg);
    border: 1px solid var(--card-border);
    backdrop-filter: blur(12px);
    border-radius: 14px;
    padding: 1.1rem;
}

.card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.card-header h2, .card-header h3 {
    font-size: 1.05rem;
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 0.4rem;
}

.card-desc {
    font-size: 0.8rem;
    color: var(--text-muted);
    margin-bottom: 1rem;
    line-height: 1.4;
}

.badge {
    padding: 0.2rem 0.6rem;
    border-radius: 6px;
    font-size: 0.72rem;
    font-weight: 600;
    text-transform: uppercase;
}

.badge.highlight {
    background: rgba(0, 242, 254, 0.15);
    color: var(--accent-blue);
