// AEGIS-ECO Frontend Logic & Interactive GIS / Saga Visualizer

const REGION_PRESETS = {
    satara: { lat: 17.6805, lon: 74.0183, name: "Satara Forest Corridor" },
    mahabaleshwar: { lat: 17.9237, lon: 73.6586, name: "Mahabaleshwar Sanctuary" },
    kolhapur: { lat: 17.4000, lon: 73.7500, name: "Koyna Buffer Zone" }
};

let currentSagaState = "IDLE";
let currentStep = 0;

document.addEventListener("DOMContentLoaded", () => {
    initGISMap();
    fetchTelemetry();

    document.getElementById("planner-form").addEventListener("submit", (e) => {
        e.preventDefault();
        initiateSagaFromForm();
    });

    setInterval(fetchTelemetry, 3000);
});

function updateCoordinates() {
    const val = document.getElementById("location-preset").value;
    const preset = REGION_PRESETS[val];
    if (preset) {
        document.getElementById("site-lat").value = preset.lat;
        document.getElementById("site-lon").value = preset.lon;
        drawGISMap(preset.lat, preset.lon);
    }
}

// Interactive Saga Execution Simulation Engine
async function initiateSagaFromForm() {
    const title = document.getElementById("project-title").value;
    const lat = parseFloat(document.getElementById("site-lat").value);
    const lon = parseFloat(document.getElementById("site-lon").value);
    const budget = parseFloat(document.getElementById("budget-requested").value);
    const simMode = document.getElementById("sim-mode").value;

    await executeSagaSimulation(title, lat, lon, budget, simMode);
}

async function runScenario(type) {
    if (type === "HAPPY") {
        document.getElementById("sim-mode").value = "HAPPY_PATH";
        await executeSagaSimulation("Western Ghats eDNA Biodiversity Survey", 17.6805, 74.0183, 350000, "HAPPY_PATH");
    } else {
        document.getElementById("sim-mode").value = "FORCE_REJECT";
        await executeSagaSimulation("Koyna Restricted Drone Corridor Mapping", 17.4500, 73.7000, 420000, "FORCE_REJECT");
    }
}

async function executeSagaSimulation(title, lat, lon, budget, mode) {
    resetSagaUI();
    const consoleBox = document.getElementById("console-output");

    // Set Regulatory Gateway Mode
    try {
        await fetch("/api/regulatory/mode", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ mode: mode })
        });
    } catch (e) {
        console.log("Using internal runtime fallback for simulation");
    }

    logConsole(`🚀 [SAGA ORCHESTRATOR] Initiated Saga for Project: '${title}'`, "system");
    logConsole(`📍 Target Site: (${lat.toFixed(4)}, ${lon.toFixed(4)}) | Requested Grant: $${budget.toLocaleString()}`, "system");

    // Step 1: Reserve Funds
    setStepState(1, "current");
    logConsole(`💳 Step 1: Dispatched 'COMMAND_RESERVE_FUNDS' to Funding Service...`, "system");
    await sleep(800);
    setStepState(1, "completed");
    logConsole(`✅ Event: 'FUNDS_RESERVED' | Reserved $${budget.toLocaleString()} from Grant 'GRANT-WESTERN-GHATS-2026'`, "success");

    // Step 2: PostGIS Resource Optimization
    setStepState(2, "current");
    logConsole(`📍 Step 2: Dispatched 'COMMAND_RESERVE_RESOURCES' (PostGIS Spatial Proximity & Scoring)...`, "system");
    drawGISMap(lat, lon, true);
    await sleep(1000);
    setStepState(2, "completed");
    logConsole(`✅ Event: 'RESOURCES_RESERVED' | PostGIS Composite Score Selected: LiDAR Drone Alpha (Pune Depot, 52km away) + eDNA Sequencer Unit-1`, "success");

    // Step 3: Assign Field Team
    setStepState(3, "current");
    logConsole(`👥 Step 3: Dispatched 'COMMAND_ASSIGN_TEAM' to Team Service...`, "system");
    await sleep(800);
    setStepState(3, "completed");
    logConsole(`✅ Event: 'TEAM_ASSIGNED' | Assigned Dr. Aris Thorne (Lead Ecologist) & Elena Rostova (Drone Operator)`, "success");

    // Step 4: Regulatory Permits
    setStepState(4, "current");
    logConsole(`🏛️ Step 4: Dispatched 'COMMAND_REQUEST_PERMIT' to Regulatory Gateway...`, "system");
    await sleep(1200);

    if (mode === "FORCE_REJECT") {
        setStepState(4, "failed");
        logConsole(`🚨 Event: 'PERMIT_REJECTED' | Rejection by Karnataka Forest Department: Site intersects protected tiger corridor.`, "danger");
        logConsole(`⚠️ [SAGA ORCHESTRATOR] Launching Compensation Cascade across all participants!`, "warning");

        await sleep(600);
        logConsole(`🔄 Dispatched 'COMMAND_RELEASE_RESOURCES' -> Released LiDAR Drone Alpha & Sequencer Unit-1`, "warning");
        await sleep(400);
        logConsole(`💵 Dispatched 'COMMAND_RELEASE_FUNDS' -> Returned $${budget.toLocaleString()} to Grant pool`, "warning");
        await sleep(400);
        logConsole(`👤 Dispatched 'COMMAND_UNASSIGN_TEAM' -> Unassigned Dr. Aris Thorne & Elena Rostova`, "warning");

        setStepState(5, "failed");
        document.getElementById("step-5").querySelector(".step-label").innerText = "Saga Compensated";
        document.getElementById("step-5").querySelector(".step-status").innerText = "CANCELLED";
        document.getElementById("saga-state-badge").className = "badge danger";
        document.getElementById("saga-state-badge").innerText = "STATE: CANCELLED (COMPENSATED)";
        logConsole(`🛑 [SAGA COMPLETE] Compensation Cascade finished cleanly. Project status: CANCELLED with full audit record.`, "danger");
    } else {
        setStepState(4, "completed");
        logConsole(`✅ Event: 'PERMIT_APPROVED' | Clearances granted by Ministry of Environment, Forest & Climate Change`, "success");

        setStepState(5, "completed");
        document.getElementById("step-5").querySelector(".step-label").innerText = "Project Activated";
        document.getElementById("step-5").querySelector(".step-status").innerText = "Field Ops Ready";
        document.getElementById("saga-state-badge").className = "badge success";
        document.getElementById("saga-state-badge").innerText = "STATE: ACTIVE";
        logConsole(`🎉 [SAGA SUCCESS] Project is now ACTIVE! Field survey operations cleared to begin.`, "success");
    }

    fetchTelemetry();
}

function resetSagaUI() {
    for (let i = 1; i <= 5; i++) {
        const item = document.getElementById(`step-${i}`);
        item.className = "step-item";
    }
    document.getElementById("console-output").innerHTML = "";
    document.getElementById("active-saga-id").innerText = "Saga ID: " + generateShortId();
    document.getElementById("saga-state-badge").className = "badge info";
    document.getElementById("saga-state-badge").innerText = "STATE: RUNNING";
}

function setStepState(stepNum, state) {
    const item = document.getElementById(`step-${stepNum}`);
    if (item) {
        item.className = `step-item ${state}`;
    }
}

function logConsole(msg, type = "system") {
    const box = document.getElementById("console-output");
    const div = document.createElement("div");
    div.className = `console-line ${type}`;
    div.innerText = `[${new Date().toLocaleTimeString()}] ${msg}`;
    box.appendChild(div);
    box.scrollTop = box.scrollHeight;
}

// PostGIS GIS Map Canvas Renderer
function initGISMap() {
    drawGISMap(17.6805, 74.0183);
}

function drawGISMap(siteLat, siteLon, drawVector = false) {
    const canvas = document.getElementById("gis-canvas");
    if (!canvas) return;
    const ctx = canvas.getContext("2d");

    const width = canvas.width;
    const height = canvas.height;

    // Clear canvas
    ctx.fillStyle = "#070B14";
    ctx.fillRect(0, 0, width, height);

    // Grid overlay
    ctx.strokeStyle = "rgba(255, 255, 255, 0.04)";
    ctx.lineWidth = 1;
    for (let x = 0; x < width; x += 40) {
        ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, height); ctx.stroke();
    }
    for (let y = 0; y < height; y += 40) {
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(width, y); ctx.stroke();
    }

    // Depots (Pune, Satara, Kolhapur)
    const depots = [
        { name: "Pune Depot (Drone Alpha)", x: 220, y: 80, color: "#00F2FE" },
        { name: "Satara Depot (Drone Beta)", x: 420, y: 180, color: "#00F2FE" },
        { name: "IISER Pune Lab (Sequencer)", x: 190, y: 110, color: "#4FACFE" },
        { name: "Kolhapur Station (GPR Radar)", x: 580, y: 280, color: "#00F2FE" }
    ];

    // Spatial Restriction Polygons (Koyna & Airspace)
    ctx.fillStyle = "rgba(255, 82, 82, 0.15)";
    ctx.strokeStyle = "rgba(255, 82, 82, 0.5)";
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(310, 190); ctx.lineTo(390, 190); ctx.lineTo(390, 260); ctx.lineTo(310, 260); ctx.closePath();
    ctx.fill(); ctx.stroke();
    ctx.fillStyle = "#FF5252";
    ctx.font = "10px Outfit";
    ctx.fillText("Koyna Restricted Sanctuary Zone", 312, 225);

    // Draw Depots
    depots.forEach(d => {
        ctx.fillStyle = d.color;
        ctx.beginPath(); ctx.arc(d.x, d.y, 6, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = "#9CA3AF";
        ctx.font = "11px Outfit";
        ctx.fillText(d.name, d.x + 10, d.y + 4);
    });

    // Draw Target Site (Mapped from coordinates)
    const targetX = 400 + (siteLon - 74.0) * 400;
    const targetY = 180 + (17.7 - siteLat) * 300;

    ctx.fillStyle = "#00E676";
    ctx.shadowColor = "#00E676";
    ctx.shadowBlur = 10;
    ctx.beginPath(); ctx.arc(targetX, targetY, 8, 0, Math.PI * 2); ctx.fill();
    ctx.shadowBlur = 0;

    ctx.fillStyle = "#FFFFFF";
    ctx.font = "bold 11px Outfit";
    ctx.fillText("TARGET SITE", targetX + 12, targetY + 4);

    // Draw Travel Vectors if active
    if (drawVector) {
        ctx.strokeStyle = "#00F2FE";
        ctx.setLineDash([4, 4]);
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(depots[0].x, depots[0].y);
        ctx.lineTo(targetX, targetY);
        ctx.stroke();
        ctx.setLineDash([]);

        ctx.fillStyle = "#00F2FE";
        ctx.font = "bold 10px JetBrains Mono";
        ctx.fillText("Optimal Route: 52 km (Transit: 1.1 hrs)", (depots[0].x + targetX) / 2, (depots[0].y + targetY) / 2);
    }
}

// Telemetry & Redis Read Model Polling
async function fetchTelemetry() {
    try {
        const res = await fetch("/api/analytics");
        const data = await res.json();

        document.getElementById("metric-total").innerText = data.metrics.total_projects;
        document.getElementById("metric-active").innerText = data.metrics.active_projects;
        document.getElementById("metric-cancelled").innerText = data.metrics.cancelled_projects;
        document.getElementById("metric-funds").innerText = "$" + data.metrics.reserved_funds.toLocaleString();

        updateAssetList();
        updateEventStream(data.recent_events);
    } catch (e) {
        // Fallback local update
        updateAssetList();
    }
}

function updateAssetList() {
    const container = document.getElementById("asset-list");
    const assets = [
        { name: "LiDAR Drone Alpha", depot: "Pune Depot", status: "AVAILABLE", batt: "95%" },
        { name: "LiDAR Drone Beta", depot: "Satara Depot", status: "AVAILABLE", batt: "88%" },
        { name: "eDNA Sequencer Unit-1", depot: "IISER Pune Lab", status: "AVAILABLE", batt: "100%" },
        { name: "Ground Radar GPR-7", depot: "Kolhapur Station", status: "AVAILABLE", batt: "75%" }
    ];

    container.innerHTML = assets.map(a => `
        <div class="asset-item">
            <div class="asset-name">
                <span>${a.name}</span>
                <span class="badge ${a.status === 'AVAILABLE' ? 'highlight' : 'info'}">${a.status}</span>
            </div>
            <div class="asset-sub">Depot: ${a.depot} | Battery: ${a.batt}</div>
        </div>
    `).join("");
}

function updateEventStream(events) {
    const container = document.getElementById("event-stream");
    if (!events || events.length === 0) {
        container.innerHTML = `<div class="event-item"><span class="event-type">aegis.project.initiated</span><span class="event-time">Now</span></div>`;
        return;
    }

    container.innerHTML = events.map(e => `
        <div class="event-item">
            <span class="event-type">${e.event_type}</span>
            <span class="event-time">${new Date(e.timestamp).toLocaleTimeString()}</span>
        </div>
    `).join("");
}

function sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
}

function generateShortId() {
    return Math.random().toString(36).substring(2, 10);
}

