    handleRouting();
    loadDashboardData();
    setInterval(loadDashboardData, 3000); // Live poll stats
});

// Routing Handler
function handleRouting() {
    const hash = window.location.hash || "#/";
    currentRoute = hash;

    // Hide all page views
    document.querySelectorAll(".page-view").forEach(el => el.classList.remove("active"));
    document.querySelectorAll(".nav-item").forEach(el => el.classList.remove("active"));

    if (hash.startsWith("#/projects/new")) {
        showView("page-projects-new", "nav-projects");
    } else if (hash.startsWith("#/projects/")) {
        const pid = hash.replace("#/projects/", "");
        activeProjectDetailId = pid;
        showView("page-project-detail", "nav-projects");
        loadProjectDetail(pid);
    } else if (hash.startsWith("#/projects")) {
        showView("page-projects-list", "nav-projects");
        loadProjectsList();
    } else if (hash.startsWith("#/resources")) {
        showView("page-resources", "nav-resources");
        loadResourcesData();
    } else if (hash.startsWith("#/system")) {
        showView("page-system", "nav-system");
        loadSystemHealth();
    } else {
        showView("page-overview", "nav-overview");
        loadOverview();
    }
}

function showView(viewId, navId) {
    const view = document.getElementById(viewId);
    if (view) view.classList.add("active");
    const nav = document.getElementById(navId);
    if (nav) nav.classList.add("active");
}

function navigateTo(hash) {
    window.location.hash = hash;
}

// ── PAGE 1: OVERVIEW ────────────────────────────────────────────────────────

async function loadOverview() {
    try {
        const res = await fetch(`${API_BASE}/analytics`);
        const data = await res.json();
        const m = data.metrics || {};

        document.getElementById("ov-total").innerText = m.total_projects || 0;
        document.getElementById("ov-active").innerText = m.active_projects || 0;
        document.getElementById("ov-pending").innerText = (m.total_projects - m.active_projects - m.cancelled_projects) || 0;
        document.getElementById("ov-compensating").innerText = m.cancelled_projects || 0;

        // Fetch recent projects list
        const pRes = await fetch(`${API_BASE}/projects`);
        const projects = await pRes.json();

        const listEl = document.getElementById("recent-projects-list");
        listEl.innerHTML = "";

        projects.slice(0, 4).forEach(p => {
            const item = document.createElement("div");
            item.className = "recent-item";
            item.onclick = () => navigateTo(`#/projects/${p.project_id}`);

            let statusClass = "active";
            if (p.status === "COMPENSATING") statusClass = "warning";
            if (p.status === "CANCELLED") statusClass = "danger";

            item.innerHTML = `
                <div>
                    <div class="project-title-sub">${p.title}</div>
                    <div class="project-location-sub">${p.location_name} • $${p.budget_requested ? p.budget_requested.toLocaleString() : "0"}</div>
                </div>
                <span class="badge ${statusClass}">${p.status}</span>
            `;
            listEl.appendChild(item);
        });

        drawGISMap("overview-map-canvas", projects);
    } catch (e) {
        console.error("Error loading overview:", e);
    }
}

// ── PAGE 2: NEW PROJECT ANALYZER ─────────────────────────────────────────────

async function analyzeDeployment() {
    const title = document.getElementById("np-title").value;
    const location = document.getElementById("np-location").value;
    const lat = document.getElementById("np-lat").value;
    const lon = document.getElementById("np-lon").value;
    const budget = document.getElementById("np-budget").value;
    const priority = document.getElementById("np-priority").value;

    const checkboxes = document.querySelectorAll("#new-project-form input[type=checkbox]:checked");
    const reqEq = Array.from(checkboxes).map(c => c.value);

    try {
        const res = await fetch(`${API_BASE}/projects/analyze`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ site_lat: lat, site_lon: lon, required_equipment: reqEq })
        });
        const data = await res.json();
        const rec = data.recommended_plan;

        const panel = document.getElementById("plan-content");
        if (rec) {
            panel.innerHTML = `
                <div class="plan-match-header">${rec.name}</div>
                <div class="plan-depot">${rec.depot_name} • ${rec.dist_km} km away • Composite Score: ${rec.score}</div>

                <div class="plan-checks">
                    <div class="check-line">✓ Spatial restrictions clear (Outside restricted polygon)</div>
                    <div class="check-line">✓ Battery ${rec.battery_pct}% available (Workload: ${rec.workload})</div>
                    <div class="check-line">✓ Within grant budget ceiling</div>
                </div>

                <button class="btn primary-btn full-btn" onclick="startProjectFromPlan('${title}', '${location}', ${lat}, ${lon}, ${budget}, '${priority}')">
                    🚀 Start Project Deployment
                </button>
            `;
        } else {
            panel.innerHTML = `<div class="placeholder-text" style="color: var(--accent-red)">No available equipment matched the criteria.</div>`;
        }
    } catch (e) {
        console.error("Error analyzing deployment:", e);
    }
}

async function startProjectFromPlan(title, location, lat, lon, budget, priority) {
    const simMode = document.getElementById("np-sim-mode").value;

    try {
        const res = await fetch(`${API_BASE}/projects/initiate`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
                title: title,
                location_name: location,
                site_lat: parseFloat(lat),
                site_lon: parseFloat(lon),
                budget_requested: parseFloat(budget),
                priority: priority,
                sim_mode: simMode
            })
        });
        const data = await res.json();
        if (data.status === "SUCCESS") {
            navigateTo(`#/projects/${data.project.project_id}`);
        }
    } catch (e) {
        console.error("Error initiating project:", e);
    }
}

// ── PAGE 3: PROJECT DETAIL ──────────────────────────────────────────────────

async function loadProjectDetail(pid) {
    try {
        const res = await fetch(`${API_BASE}/projects/${pid}`);
        const p = await res.json();

        let statusClass = "active";
        if (p.status === "COMPENSATING") statusClass = "warning";
        if (p.status === "CANCELLED") statusClass = "danger";

        const headerEl = document.getElementById("pd-header");
        headerEl.innerHTML = `
            <div>
                <h2>${p.title}</h2>
                <p class="subtitle">${p.location_name} • Initiated ${p.created_at || "Recently"}</p>
            </div>
            <div style="text-align: right">
                <span class="badge ${statusClass}" style="font-size: 0.9rem">${p.status}</span>
                <div style="font-size: 0.78rem; color: var(--text-muted); margin-top: 0.35rem">Saga #${pid.substring(0, 8).toUpperCase()}</div>
            </div>
        `;

        // Render Allocated
        const allocEl = document.getElementById("pd-allocated-list");
        allocEl.innerHTML = `
            <div style="margin-bottom: 0.75rem"><strong>Equipments:</strong> ${(p.required_equipment || []).join(", ")}</div>
            <div style="margin-bottom: 0.75rem"><strong>Team:</strong> ${(p.required_team || []).join(", ")}</div>
            <div><strong>Permit Status:</strong> <span class="badge success">APPROVED</span></div>
        `;

        // Render Saga Stepper
        const stepperEl = document.getElementById("pd-saga-stepper");
        stepperEl.innerHTML = `
            <div class="step-node done"><div class="step-icon">✓</div><div>Funds Reserved ($${p.budget_requested ? p.budget_requested.toLocaleString() : "0"})</div></div>
            <div class="step-node done"><div class="step-icon">✓</div><div>PostGIS Equipment Allocated</div></div>
            <div class="step-node done"><div class="step-icon">✓</div><div>Field Specialist Assigned</div></div>
            <div class="step-node ${p.status === 'CANCELLED' ? 'danger' : 'done'}"><div class="step-icon">${p.status === 'CANCELLED' ? '✗' : '✓'}</div><div>Regulatory Clearance (${p.status === 'CANCELLED' ? 'REJECTED' : 'APPROVED'})</div></div>
            <div class="step-node ${p.status === 'ACTIVE' ? 'active' : ''}"><div class="step-icon">${p.status === 'ACTIVE' ? '◉' : '○'}</div><div>${p.status === 'ACTIVE' ? 'Project Activated' : p.status}</div></div>
        `;

        // Audit Logs
        const logEl = document.getElementById("pd-audit-log");
        logEl.innerHTML = (p.saga_log || []).map(l => `<div>[${l.created_at || 'LOG'}] ${l.step} | ${l.status} | ${l.details}</div>`).join("");

        drawGISMap("detail-map-canvas", [p]);
    } catch (e) {
        console.error("Error loading project detail:", e);
    }
}

function switchDetailTab(tab) {
    document.querySelectorAll(".tab-btn").forEach(b => b.classList.remove("active"));
    document.querySelectorAll(".detail-tab-content").forEach(c => c.classList.remove("active"));

    if (tab === "saga") {
        document.querySelectorAll(".tab-btn")[1].classList.add("active");
        document.getElementById("pd-tab-saga").classList.add("active");
    } else {
        document.querySelectorAll(".tab-btn")[0].classList.add("active");
        document.getElementById("pd-tab-overview").classList.add("active");
    }
}

