// ── GIS CANVAS MAP RENDERER ──────────────────────────────────────────────────

function drawGISMap(canvasId, projects = []) {
    const canvas = document.getElementById(canvasId);
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    const width = canvas.width;
    const height = canvas.height;

    // Clear background
    ctx.fillStyle = "#020617";
    ctx.fillRect(0, 0, width, height);

    // Draw Map Grid / Topo Lines
    ctx.strokeStyle = "rgba(0, 242, 254, 0.08)";
    ctx.lineWidth = 1;
    for (let x = 0; x < width; x += 40) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, height);
        ctx.stroke();
    }
    for (let y = 0; y < height; y += 40) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
    }

    // Draw Restricted Polygon (Koyna Sanctuary)
    ctx.fillStyle = "rgba(239, 68, 68, 0.12)";
    ctx.strokeStyle = "rgba(239, 68, 68, 0.5)";
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(250, 100);
    ctx.lineTo(380, 100);
    ctx.lineTo(380, 220);
    ctx.lineTo(250, 220);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = "#EF4444";
    ctx.font = "10px sans-serif";
    ctx.fillText("Koyna Restricted Polygon", 255, 115);

    // Plot Pune / Satara / Kolhapur Depots
    const depots = [
        { name: "Pune Depot", x: 420, y: 70 },
        { name: "Satara Depot", x: 480, y: 170 },
        { name: "Kolhapur Depot", x: 550, y: 270 }
    ];

    depots.forEach(d => {
        ctx.fillStyle = "#00F2FE";
        ctx.beginPath();
        ctx.arc(d.x, d.y, 6, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = "#94A3B8";
        ctx.fillText(d.name, d.x + 10, d.y + 4);
    });

    // Plot Projects
    projects.forEach((p, idx) => {
        const px = 200 + (idx * 90) % 300;
        const py = 120 + (idx * 60) % 150;

        ctx.fillStyle = p.status === "CANCELLED" ? "#EF4444" : "#10B981";
        ctx.beginPath();
        ctx.arc(px, py, 8, 0, Math.PI * 2);
        ctx.fill();

        ctx.strokeStyle = "#FFFFFF";
        ctx.lineWidth = 2;
        ctx.stroke();

        ctx.fillStyle = "#F8FAFC";
        ctx.font = "11px sans-serif";
        ctx.fillText(p.title || "Project", px + 12, py + 4);
    });
}

function loadDashboardData() {
    if (currentRoute === "#/" || currentRoute === "#/overview") {
        loadOverview();
    }
}

:root {
    --bg-dark: #0D1410;
    --card-bg: #141E18;
    --card-border: rgba(255, 255, 255, 0.08);
    --accent-moss: #3E7350;
    --accent-sage: #7AA387;
    --accent-olive: #97B59F;
    --accent-stone: #C5CCC6;
    --accent-amber: #D97706;
    --accent-red: #DC2626;
    --text-main: #F0F4F1;
    --text-muted: #8E9F94;
    --font-heading: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    background-color: var(--bg-dark);
    color: var(--text-main);
    font-family: var(--font-heading);
    min-height: 100vh;
}

.app-wrapper {
    display: flex;
    flex-direction: column;
    min-height: 100vh;
    padding: 1.25rem 2rem;
    gap: 1.5rem;
    max-width: 1440px;
    margin: 0 auto;
}

/* Header Navbar */
.top-nav {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: var(--card-bg);
    border: 1px solid var(--card-border);
    border-radius: 8px;
    padding: 0.85rem 1.5rem;
}

.nav-brand {
    display: flex;
    align-items: baseline;
    gap: 0.75rem;
    cursor: pointer;
}

.brand-title {
    font-size: 1.25rem;
    font-weight: 700;
    letter-spacing: 1px;
    color: var(--text-main);
}

.brand-subtitle {
    font-size: 0.75rem;
    color: var(--accent-sage);
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

/* Navigation Links */
.nav-links {
    display: flex;
    align-items: center;
    gap: 1.5rem;
}

.nav-item {
    color: var(--text-muted);
    text-decoration: none;
    font-size: 0.9rem;
    font-weight: 500;
    padding: 0.35rem 0.65rem;
    border-radius: 4px;
    transition: all 0.2s ease;
}

.nav-item:hover, .nav-item.active {
    color: var(--text-main);
    background: rgba(122, 163, 135, 0.12);
}

.nav-dropdown {
    position: relative;
}

.nav-dropdown:hover .dropdown-menu {
    display: flex;
}

.dropdown-menu {
    display: none;
    flex-direction: column;
    position: absolute;
    top: 100%;
    left: 0;
    background: #111A14;
    border: 1px solid var(--card-border);
    border-radius: 6px;
    padding: 0.5rem;
    min-width: 150px;
    box-shadow: 0 10px 25px rgba(0, 0, 0, 0.5);
    z-index: 100;
}

.dropdown-menu a {
    color: var(--text-muted);
    text-decoration: none;
    font-size: 0.85rem;
    padding: 0.4rem 0.75rem;
    border-radius: 4px;
}

.dropdown-menu a:hover {
    color: var(--text-main);
    background: rgba(255, 255, 255, 0.05);
}

/* Section Title Bar */
.section-title-bar h2 {
    font-size: 1.35rem;
    font-weight: 600;
    color: var(--text-main);
    border-bottom: 1px solid var(--card-border);
    padding-bottom: 0.5rem;
}

/* Page Views */
.page-container {
    flex: 1;
}

.page-view {
    display: none;
    flex-direction: column;
    gap: 1.25rem;
}

.page-view.active {
    display: flex;
}

/* Cards & Layout */
.card {
    background: var(--card-bg);
    border: 1px solid var(--card-border);
    border-radius: 8px;
    padding: 1.25rem;
}

.card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.card-header h3 {
    font-size: 1rem;
    font-weight: 600;
    color: var(--text-main);
}

/* Stats Overview Grid */
.stats-overview-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1rem;
}

.stat-card {
    background: var(--card-bg);
    border: 1px solid var(--card-border);
    border-radius: 8px;
    padding: 1rem 1.25rem;
}

.stat-num {
    font-size: 2.1rem;
    font-weight: 700;
    color: var(--text-main);
}

.stat-card.success .stat-num { color: var(--accent-sage); }
.stat-card.warning .stat-num { color: var(--accent-amber); }
.stat-card.danger .stat-num { color: var(--accent-red); }

.stat-label {
    font-size: 0.78rem;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-top: 0.2rem;
}

/* Overview Body Layout */
.overview-body-grid {
    display: grid;
    grid-template-columns: 2fr 1fr;
    gap: 1.25rem;
}

.map-wrapper {
    width: 100%;
    height: 380px;
    border-radius: 6px;
    overflow: hidden;
    background: #090E0B;
}

#overview-leaflet-map, #detail-leaflet-map {
