/* Status Badges */
.badge {
    font-size: 0.72rem;
    padding: 0.2rem 0.55rem;
    border-radius: 4px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.badge.active, .badge.success { background: rgba(62, 115, 80, 0.25); color: var(--accent-sage); border: 1px solid rgba(122, 163, 135, 0.3); }
.badge.compensating, .badge.warning { background: rgba(217, 119, 6, 0.2); color: var(--accent-amber); border: 1px solid rgba(217, 119, 6, 0.3); }
.badge.cancelled, .badge.danger { background: rgba(220, 38, 38, 0.2); color: var(--accent-red); border: 1px solid rgba(220, 38, 38, 0.3); }
.badge.info { background: rgba(151, 181, 159, 0.2); color: var(--accent-stone); border: 1px solid rgba(151, 181, 159, 0.3); }

/* Buttons */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0.6rem 1.25rem;
    border-radius: 6px;
    font-size: 0.88rem;
    font-weight: 600;
    border: none;
    cursor: pointer;
    transition: all 0.2s ease;
    text-decoration: none;
}

.primary-btn {
    background: var(--accent-moss);
    color: #F0F4F1;
}

.primary-btn:hover {
    background: #49825C;
}

.secondary-btn {
    background: rgba(255, 255, 255, 0.05);
    color: var(--text-main);
    border: 1px solid var(--card-border);
}

.secondary-btn:hover {
    background: rgba(255, 255, 255, 0.1);
}

.btn-sm { padding: 0.35rem 0.75rem; font-size: 0.8rem; }
.full-btn { width: 100%; margin-top: 1rem; }

/* New Project Form & Accordions */
.new-project-grid {
    display: grid;
    grid-template-columns: 1.2fr 1fr;
    gap: 1.25rem;
}

.form-section {
    background: rgba(255, 255, 255, 0.02);
    border: 1px solid var(--card-border);
    border-radius: 6px;
    margin-bottom: 0.75rem;
    overflow: hidden;
}

.form-section summary {
    padding: 0.75rem 1rem;
    font-weight: 600;
    font-size: 0.9rem;
    cursor: pointer;
    user-select: none;
    background: rgba(255, 255, 255, 0.03);
}

.form-content {
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.form-group {
