        const headerEl = document.getElementById("pd-header");
        headerEl.innerHTML = `
            <div>
                <h2>${p.title}</h2>
                <p class="subtitle">${p.location_name} • Initiated ${p.created_at || "Recently"}</p>
            </div>
            <div style="text-align: right">
                <span class="badge ${statusClass}">${p.status}</span>
                <div style="font-size: 0.78rem; color: var(--text-muted); margin-top: 0.35rem">Saga #${pid.substring(0, 8).toUpperCase()}</div>
            </div>
        `;

        const allocEl = document.getElementById("pd-allocated-list");
        allocEl.innerHTML = `
            <div style="margin-bottom: 0.75rem"><strong>Equipment:</strong> ${(p.required_equipment || []).join(", ")}</div>
            <div style="margin-bottom: 0.75rem"><strong>Team:</strong> ${(p.required_team || []).join(", ")}</div>
            <div><strong>Permit Status:</strong> <span class="badge success">APPROVED</span></div>
        `;

        const stepperEl = document.getElementById("pd-saga-stepper");
        stepperEl.innerHTML = `
            <div class="step-node done"><div class="step-icon">✓</div><div>Funds Reserved ($${p.budget_requested ? p.budget_requested.toLocaleString() : "0"})</div></div>
            <div class="step-node done"><div class="step-icon">✓</div><div>PostGIS Equipment Allocated</div></div>
            <div class="step-node done"><div class="step-icon">✓</div><div>Field Specialist Assigned</div></div>
            <div class="step-node ${p.status === 'CANCELLED' ? 'danger' : 'done'}"><div class="step-icon">${p.status === 'CANCELLED' ? '✗' : '✓'}</div><div>Regulatory Clearance (${p.status === 'CANCELLED' ? 'REJECTED' : 'APPROVED'})</div></div>
            <div class="step-node ${p.status === 'ACTIVE' ? 'active' : ''}"><div class="step-icon">${p.status === 'ACTIVE' ? '◉' : '○'}</div><div>${p.status === 'ACTIVE' ? 'Project Activated' : p.status}</div></div>
        `;

        const logEl = document.getElementById("pd-audit-log");
        logEl.innerHTML = (p.saga_log || []).map(l => `<div>[${l.created_at || 'LOG'}] ${l.step} | ${l.status} | ${l.details}</div>`).join("");

        initDetailLeafletMap(p.site_lat, p.site_lon, p.title);
    } catch (e) {
        console.error("Error loading project detail:", e);
    }
}

function switchDetailTab(tab) {
    document.querySelectorAll(".tab-btn").forEach(b => b.classList.remove("active"));
    document.querySelectorAll(".detail-tab-content").forEach(c => c.classList.remove("active"));

    if (tab === "saga") {
