@import url('https://fonts.cdnfonts.com/css/garet');

:root {
    --bg-dark: #090D0A;
    --surface-dark: #111612;
    --surface-elevated: #18201A;
    --parchment: #E6DFD5;
    --parchment-muted: #B8B0A2;
    --stone: #8C8477;
    --moss: #4C775A;
    --moss-light: #6A9E7B;
