    --rust: #C24F4F;
    --border-subtle: rgba(230, 223, 213, 0.08);
    --border-medium: rgba(230, 223, 213, 0.15);
}

* {
    box-sizing: border-box;
}

body {
    background: var(--bg-dark);
    color: var(--parchment);
    font-family: 'Garet', 'Inter', sans-serif;
    margin: 0;
    padding: 0;
    line-height: 1.5;
    background-image: radial-gradient(rgba(76, 119, 90, 0.05) 1px, transparent 1px);
    background-size: 24px 24px;
}

h1, h2, h3, h4 {
