    padding: 8px 12px !important;
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.5) !important;
}

.leaflet-control-layers-base label {
    display: flex;
    align-items: center;
    gap: 6px;
    cursor: pointer;
    margin-bottom: 4px;
    color: var(--parchment-muted);
}

.leaflet-control-layers-base label:hover {
    color: var(--parchment);
}

/* Ledger List (No Card Rectangles) */
.expeditions-ledger {
    margin-top: 2rem;
}

.expeditions-ledger h2 {
    font-size: 1.1rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--stone);
    margin-bottom: 1rem;
    border-bottom: 1px solid var(--border-subtle);
    padding-bottom: 0.5rem;
}

.ledger-table {
    width: 100%;
    border-collapse: collapse;
}

.ledger-table th {
    text-align: left;
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.75rem;
    color: var(--stone);
    text-transform: uppercase;
    padding: 0.75rem 0;
    border-bottom: 1px solid var(--border-medium);
}

.ledger-table td {
    padding: 1rem 0;
    border-bottom: 1px solid var(--border-subtle);
    font-size: 0.9rem;
}

.ledger-row {
    cursor: pointer;
    transition: background 0.15s ease;
}

.ledger-row:hover td {
    color: var(--moss-light);
}

.status-tag {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.75rem;
    letter-spacing: 0.05em;
    text-transform: uppercase;
}

.status-tag.active { color: var(--moss-light); }
.status-tag.pending { color: var(--clay); }
.status-tag.cancelled, .status-tag.failed { color: var(--rust); }
.status-tag.compensating { color: var(--rust); }

/* Custom Cartographic Map Symbols */
.atlas-marker {
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 16px;
    font-weight: bold;
    color: var(--moss-light);
    text-shadow: 0 0 6px rgba(0,0,0,0.9);
    cursor: pointer;
}

.atlas-marker.cancelled, .atlas-marker.compensating {
