    // Add default filtered class for topographic basemaps
    map.getContainer().classList.add('map-filtered');

    const baseLayers = {
        "CARTO Voyager (Vibrant Topo)": L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png', {
