            attribution: 'Esri World Imagery', maxZoom: 18
        })
    };

    // Default layer: CARTO Voyager
    baseLayers["CARTO Voyager (Vibrant Topo)"].addTo(map);

    // Map Theme Switcher on Bottom Right
    L.control.layers(baseLayers, null, { position: 'bottomright', collapsed: false }).addTo(map);

    // Toggle filter on layer change: Satellite Aerial stays 100% natural and unfiltered!
