// ── OVERVIEW PAGE (OPERATIONS ATLAS) ────────────────────────────────────

async function loadOverview() {
    try {
        const res = await fetch(`${API_BASE}/analytics`);
        const data = await res.json();
        const m = data.metrics || {};

        document.getElementById("stat-total").innerText = m.total_projects || 0;
        document.getElementById("stat-active").innerText = m.active_projects || 0;
        document.getElementById("stat-pending").innerText = m.pending_projects || 0;
        document.getElementById("stat-compensating").innerText = m.compensating_projects || 0;

        const pRes = await fetch(`${API_BASE}/projects`);
        const projects = await pRes.json();

        renderRecentExpeditionsLedger(projects);
        initOverviewMap(projects);
    } catch (e) {
        console.error("Error loading operations atlas:", e);
    }
}

function renderRecentExpeditionsLedger(projects) {
    const tbody = document.getElementById("recent-expeditions-body");
    tbody.innerHTML = "";

    projects.slice(0, 6).forEach(p => {
        const tr = document.createElement("tr");
        tr.className = "ledger-row";
        tr.onclick = () => navigateTo(`#/projects/${p.project_id}`);

        const statusCls = (p.status || "active").toLowerCase();
        tr.innerHTML = `
            <td style="font-weight: 600;">${p.title}</td>
            <td style="color: var(--stone);">${p.location_name}</td>
            <td><span class="status-tag ${statusCls}">● ${p.status}</span></td>
            <td style="font-family: monospace;">₹${p.budget_requested ? p.budget_requested.toLocaleString() : '350,000'}</td>
            <td><a href="#/projects/${p.project_id}" class="btn secondary-btn" style="padding: 0.25rem 0.6rem; font-size: 0.75rem;">View Expedition →</a></td>
        `;
        tbody.appendChild(tr);
    });
}

async function initOverviewMap(projects) {
    if (overviewMap) {
        overviewMap.remove();
        overviewMap = null;
    }
    // Focused Regional View: Western Ghats Biodiversity Corridor (17.65°N, 73.85°E, zoom 8.5)
    overviewMap = createMap("overview-map", 17.65, 73.85, 8.5);
    addKoynaOverlay(overviewMap);

    // Plot all project locations with cartographic symbol '◉'
    projects.forEach(p => {
        if (p.site_lat && p.site_lon) {
            const cls = (p.status === "CANCELLED" || p.status === "COMPENSATING") ? "atlas-marker compensating" : "atlas-marker";
            const icon = L.divIcon({
                className: cls,
                html: '◉',
                iconSize: [20, 20]
            });
            const marker = L.marker([p.site_lat, p.site_lon], { icon, title: p.title }).addTo(overviewMap);
            marker.on('click', () => navigateTo(`#/projects/${p.project_id}`));
        }
    });

    // Also plot equipment depots and teams
    try {
        const rRes = await fetch(`${API_BASE}/resources`);
        const rData = await rRes.json();
        (rData.resources || []).forEach(r => {
            if (r.lat && r.lon) {
                const icon = L.divIcon({ className: "atlas-marker depot", html: '◇', iconSize: [18, 18] });
                L.marker([r.lat, r.lon], { icon, title: `${r.name} (${r.depot_name})` }).addTo(overviewMap);
            }
        });
    } catch(e) {}
}

