async function initOverviewMap(projects) {
    if (overviewMap) {
        overviewMap.remove();
        overviewMap = null;
    }
    // Focused Regional View: Western Ghats Biodiversity Corridor (17.65°N, 73.85°E, zoom 8.5)
    overviewMap = createMap("overview-map", 17.65, 73.85, 8.5);
    addKoynaOverlay(overviewMap);

    // Plot all project locations with round cartographic badges (size 28px)
    projects.forEach(p => {
        if (p.site_lat && p.site_lon) {
            const cls = (p.status === "CANCELLED" || p.status === "COMPENSATING") ? "atlas-marker compensating" : "atlas-marker";
            const icon = L.divIcon({
                className: cls,
                html: '●',
                iconSize: [28, 28]
            });
            const marker = L.marker([p.site_lat, p.site_lon], { icon, title: p.title }).addTo(overviewMap);
            marker.on('click', () => navigateTo(`#/projects/${p.project_id}`));
        }
    });

    // Also plot equipment depots and teams
    try {
        const rRes = await fetch(`${API_BASE}/resources`);
        const rData = await rRes.json();
        (rData.resources || []).forEach(r => {
            if (r.lat && r.lon) {
                const icon = L.divIcon({ className: "atlas-marker depot", html: '◇', iconSize: [28, 28] });
                L.marker([r.lat, r.lon], { icon, title: `${r.name} (${r.depot_name})` }).addTo(overviewMap);
            }
        });
    } catch(e) {}
}

