let _npDrawnItems = null;
let _npPolygonGeoJSON = null;

function initNewProject() {
  if (newProjectMap) { newProjectMap.remove(); newProjectMap = null; }
  _npPolygonGeoJSON = null;
  setTimeout(() => {
    newProjectMap = createMap('new-project-map', 17.45, 73.72, 9);

    _npDrawnItems = new L.FeatureGroup();
    newProjectMap.addLayer(_npDrawnItems);

    const drawControl = new L.Control.Draw({
      draw: {
        polyline: false,
        polygon: {
          allowIntersection: false,
          shapeOptions: {
            color: '#B8860B',
            fillOpacity: 0.2
          }
        },
        circle: false,
        circlemarker: false,
        marker: true,
        rectangle: {
          shapeOptions: {
            color: '#B8860B',
            fillOpacity: 0.2
          }
        }
      },
      edit: {
        featureGroup: _npDrawnItems,
        remove: true
      }
    });
    newProjectMap.addControl(drawControl);

    newProjectMap.on(L.Draw.Event.CREATED, function (event) {
      const layer = event.layer;
      _npDrawnItems.clearLayers();
      _npDrawnItems.addLayer(layer);

      let lat, lon;
      if (layer instanceof L.Marker) {
        lat = layer.getLatLng().lat;
        lon = layer.getLatLng().lng;
        _npPolygonGeoJSON = null;
      } else {
        const bounds = layer.getBounds();
        const center = bounds.getCenter();
        lat = center.lat;
        lon = center.lng;
        _npPolygonGeoJSON = layer.toGeoJSON().geometry;
      }

      document.getElementById('np-lat').value = lat.toFixed(4);
      document.getElementById('np-lon').value = lon.toFixed(4);
    });

    document.getElementById('np-lat').addEventListener('change', updateNewProjectMap);
    document.getElementById('np-lon').addEventListener('change', updateNewProjectMap);
    updateNewProjectMap();
  }, 100);
}

function updateNewProjectMap() {
  const lat = parseFloat(document.getElementById('np-lat').value);
  const lon = parseFloat(document.getElementById('np-lon').value);
  if (!isNaN(lat) && !isNaN(lon) && newProjectMap) {
    if (_npPolygonGeoJSON) return; // If polygon drawn, keep it

    _npDrawnItems.clearLayers();
    const icon = L.divIcon({ className: 'atlas-marker', html: '◉', iconSize: [20,20] });
    const marker = L.marker([lat, lon], { icon, draggable: true });

    marker.on('dragend', () => {
      const pos = marker.getLatLng();
      document.getElementById('np-lat').value = pos.lat.toFixed(4);
      document.getElementById('np-lon').value = pos.lng.toFixed(4);
    });

    _npDrawnItems.addLayer(marker);
  }
}

