import json
import os

transcript_path = r"C:\Users\Aayush\.gemini\antigravity\brain\eb942f55-b4bb-496b-abbc-5647862f7004\.system_generated\logs\transcript_full.jsonl"

edits = []

with open(transcript_path, 'r', encoding='utf-8') as f:
    for line in f:
        if not line.strip(): continue
        step = json.loads(line)
        if "tool_calls" in step:
            for tc in step["tool_calls"]:
                name = tc.get("name")
                args = tc.get("arguments", {})

                # Only keep edits targeting our project files (ignore artifacts)
                target = args.get("TargetFile") or args.get("AbsolutePath")
                if target and "brain" in target:
                    continue

                if name == "replace_file_content":
                    edits.append({
                        "type": "replace",
                        "file": target,
                        "target": args.get("TargetContent"),
                        "replacement": args.get("ReplacementContent")
                    })
                elif name == "write_to_file":
                    edits.append({
                        "type": "write",
                        "file": target,
                        "content": args.get("CodeContent")
                    })

print(f"Found {len(edits)} edits.")
for i, e in enumerate(edits):
    print(f"Edit {i}: {e['type']} on {e['file']}")

# Function to apply edit
def apply_edits(edit_list):
    for i, e in enumerate(edit_list):
        path = e['file']

        # Skip if not targeting project
        if not path or 'projects\\ecotone' not in path.lower():
            continue

        print(f"Applying {i}: {e['type']} to {os.path.basename(path)}")

        if e['type'] == 'write':
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, 'w', encoding='utf-8') as f:
                f.write(e['content'])
        elif e['type'] == 'replace':
            if not os.path.exists(path):
                print(f"File {path} not found!")
                continue

            with open(path, 'r', encoding='utf-8') as f:
                content = f.read()

            # Simple replacement
            if e['target'] in content:
                content = content.replace(e['target'], e['replacement'])
                with open(path, 'w', encoding='utf-8') as f:
                    f.write(content)
            else:
                print(f"Warning: target string not found in {path} for edit {i}")

apply_edits(edits)
